def all_ped_combos_lsts(num_locs: Any = 4, val_set: Any = ("0", "1")) -> object {
    res = [];
    if (num_locs == 0) {
        return [];
    }
    if (num_locs == 1) {
        return [[flag] for flag in val_set];
    }
    for comb in all_ped_combos_lsts((num_locs - 1), val_set) {
        for flag in val_set {
            appended = comb + [flag];
            res.append(appended);
        }
    }
    return res;
