"""
    Format a note for gedcom output
    """
def build_note(
    text: Any,
    level: Any = 1,
    limit: Any = 180,
    strip: Any = True,
    keyword: Any = "NOTE"
) -> object {
    note = [];
    key = int(level);
    tag = keyword;
    data = text;
    if strip {
        data = data.strip();
    }
    while (data != "") {
        index = limit;
        if (len(data) < limit) {
            index = len(data);
        } else {
            while ((data[(index - 1)] == " ") and (index > 0)) {
                index = index - 1;
            }
        }
        chunk = data[:index];
        data = data[index:];
        `entry = "{0} {1} {2}".format(key, tag, chunk);
        note.append(`entry);
        tag = "CONC";
        key = int(level) + 1;
    }
    return note;
}

""" convert CIE1976 'v' to CIE1931 xy coordinates
    :param u76: ' value (CIE1976)
    :param v76: v' value (CIE1976)
    :return: CIE1931 x, y """
def uv76_to_xy(u76: Any, v76: Any) -> object {
    denominator = (((9 * u76) / 2) - (12 * v76)) + 9;
    if (denominator == 0.0) {
        (x, y) = (0.0, 0.0);
    } else {
        x = (27 * u76) / 4 / denominator;
        y = (3 * v76) / denominator;
    }
    return (x, y);
}

