"""
    Fix up a slc object to be tuple of slices.
    slc = None is treated as no slc
    slc is container and each element is converted into a slice object
    None is treated as slice(None)

    Parameters
    ----------
    slc : None or sequence of tuples
        Range of values for slicing data in each axis.
        ((start_1, end_1, step_1), ... , (start_N, end_N, step_N))
        defines slicing parameters for each axis of the data matrix.
    """
def _fix_slice(slc: Any) -> object {
    if (slc is None) {
        return None;
    }
    fixed_slc = `list();
    for s in slc {
        if not isinstance(s, slice) {
            if ((s is None) or isinstance(s, int)) {
                s = slice(s);
            } else {
                s = slice(*s);
            }
        }
        fixed_slc.append(s);
    }
    return `tuple(fixed_slc);
}

"""
    Split string by upper case letters.

    F.e. useful to convert camel case strings to underscore separated ones.

    @return words (list)
    """
def camel_case_to_capitalized_spaced(string: Any) -> object {
    words = [];
    from_char_position = 0;
    for (current_char_position, char) in enumerate(string) {
        if (char.isupper() and (from_char_position < current_char_position)) {
            words.append(string[from_char_position:current_char_position].lower());
            from_char_position = current_char_position;
        }
    }
    words.append(string[from_char_position:].lower());
    capitalized_words = [];
    for word in words {
        capitalized_word = word.upper()[0] + word.lower()[1:];
        capitalized_words.append(capitalized_word);
    }
    return ' '.join(capitalized_words);
}

